fn new(title: String) -> Self {
    let proposal = AgentProposal::default();
    Self {
        schema_version: SESSION_SCHEMA_VERSION,
        id: next_id("session"),
        title,
        messages: Vec::new(),
        proposal: proposal.clone(),
        proposal_history: vec![proposal],
        runs: Vec::new(),
        shared_with_project: false,
    }
}
